<script setup lang="ts">
import {ref,watch,nextTick,onMounted,onBeforeUnmount} from 'vue'
const props=defineProps<{open:boolean;active:'media'|'ai';hasAI:boolean;top:number}>()
const emit=defineEmits<{(e:'close'):void;(e:'tab',value:'media'|'ai'):void}>()
const panel=ref<HTMLElement>(),mobile=ref(false),viewportHeight=ref(0),viewportOffset=ref(0)
let previous:HTMLElement|null=null,oldOverflow='',locked=false,query:MediaQueryList|undefined
function release(){if(locked){document.body.style.overflow=oldOverflow;locked=false}}
function resize(){viewportHeight.value=window.visualViewport?.height||window.innerHeight;viewportOffset.value=window.visualViewport?.offsetTop||0;mobile.value=!!query?.matches;if(props.open&&mobile.value&&!locked){oldOverflow=document.body.style.overflow;document.body.style.overflow='hidden';locked=true}else if(!mobile.value)release()}
onMounted(()=>{query=window.matchMedia?.('(max-width: 767px)');query?.addEventListener('change',resize);window.visualViewport?.addEventListener('resize',resize);window.visualViewport?.addEventListener('scroll',resize);resize()})
watch(()=>props.open,async open=>{if(open){previous=document.activeElement instanceof HTMLElement?document.activeElement:null;resize();await nextTick();panel.value?.querySelector<HTMLButtonElement>('[data-close]')?.focus({preventScroll:true})}else{release();previous?.focus({preventScroll:true})}},{flush:'post'})
function key(e:KeyboardEvent){if(e.key==='Escape'){e.preventDefault();e.stopPropagation();emit('close');return}if(e.key!=='Tab'||!mobile.value)return
 const controls=Array.from(panel.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href],[tabindex="0"]')||[]).filter(el=>!el.closest('[hidden]')&&el.getClientRects().length)
 const first=controls[0],last=controls.at(-1);if(!first){e.preventDefault();return}if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
onBeforeUnmount(()=>{release();query?.removeEventListener('change',resize);window.visualViewport?.removeEventListener('resize',resize);window.visualViewport?.removeEventListener('scroll',resize)})
</script>
<template><aside v-show="open" ref="panel" class="editor-tools" :style="{'--tools-top':top+'px','--tools-height':viewportHeight?viewportHeight+'px':undefined,'--tools-offset':viewportOffset+'px'}" :role="mobile?'dialog':'region'" :aria-modal="mobile?'true':undefined" aria-label="写作侧边工作区" @keydown="key"><header><strong>写作工具</strong><button data-close type="button" class="quiet" @click="emit('close')" aria-label="关闭写作工作区">关闭</button></header><nav aria-label="写作工具切换"><button type="button" :aria-pressed="active==='media'" @click="emit('tab','media')">媒体库</button><button v-if="hasAI" type="button" :aria-pressed="active==='ai'" @click="emit('tab','ai')">AI 助手</button></nav><div class="editor-tools-scroll"><div v-show="active==='media'" :hidden="active!=='media'"><slot name="media"/></div><div v-show="active==='ai'" :hidden="active!=='ai'"><slot name="ai"/></div></div><footer v-if="$slots.footer" class="editor-tools-actions"><slot name="footer"/></footer></aside></template>
<style scoped>
.editor-tools{position:fixed;z-index:65;inset:calc(var(--tools-top) + 12px) 12px 12px auto;width:min(368px,calc(100vw - 24px));display:flex;flex-direction:column;min-width:0;max-height:calc(100dvh - var(--tools-top) - 24px);background:var(--paper,var(--ui-card));color:var(--ink,var(--ui-text));border:1px solid var(--line,var(--ui-line));border-radius:16px;box-shadow:0 12px 36px #0002;overflow:hidden;overflow-anchor:none}.editor-tools header,.editor-tools nav{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:12px;border-bottom:1px solid var(--line,var(--ui-line))}.editor-tools nav{justify-content:flex-start}.editor-tools nav button[aria-pressed=true]{outline:2px solid var(--accent);outline-offset:1px}.editor-tools-actions{flex:0 0 auto;padding:12px 16px max(12px,env(safe-area-inset-bottom));border-top:1px solid var(--line,var(--ui-line));background:var(--paper,var(--ui-card))}.editor-tools-scroll{overflow:auto;overscroll-behavior:contain;padding:16px;min-height:0;min-width:0}.editor-tools :deep(input),.editor-tools :deep(select),.editor-tools :deep(textarea){max-width:100%;box-sizing:border-box}.editor-tools :deep(fieldset){min-width:0}.editor-tools :deep(.actions){flex-wrap:wrap}
@media(max-width:767px){.editor-tools{inset:var(--tools-offset,0px) 0 auto;width:auto;height:var(--tools-height,100dvh);max-height:var(--tools-height,100dvh);border-radius:0;padding-bottom:env(safe-area-inset-bottom)}.editor-tools header{padding-top:max(12px,env(safe-area-inset-top))}}
</style>
